CREATE TABLE im_conversations(id BIGINT PRIMARY KEY AUTO_INCREMENT,type VARCHAR(32) NOT NULL CHECK(type IN ('direct','group')),title VARCHAR(255),created_at BIGINT NOT NULL DEFAULT (UNIX_TIMESTAMP()),updated_at BIGINT NOT NULL DEFAULT (UNIX_TIMESTAMP())) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE im_conversation_members(conversation_id BIGINT NOT NULL,user_id BIGINT NOT NULL,joined_at BIGINT NOT NULL DEFAULT (UNIX_TIMESTAMP()),last_read_message_id BIGINT,PRIMARY KEY(conversation_id,user_id),FOREIGN KEY (conversation_id) REFERENCES im_conversations(id),FOREIGN KEY (user_id) REFERENCES loom_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE INDEX im_conversation_members_user ON im_conversation_members(user_id,conversation_id);
CREATE TABLE im_messages(id BIGINT PRIMARY KEY AUTO_INCREMENT,conversation_id BIGINT NOT NULL,user_id BIGINT NOT NULL,body LONGTEXT NOT NULL,created_at BIGINT NOT NULL DEFAULT (UNIX_TIMESTAMP()),FOREIGN KEY (conversation_id) REFERENCES im_conversations(id),FOREIGN KEY (user_id) REFERENCES loom_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE INDEX im_messages_conversation ON im_messages(conversation_id,id);
